  "Fluids (drip or under the skin)": "ద్రవాలు (డ్రిప్ లేదా చర్మం కింద)",
  "Follow the existing prescription. This list does not change medicines or doses.": "ఉన్న ప్రిస్క్రిప్షన్ ప్రకారమే చేయండి. ఈ జాబితా మందులను గానీ మోతాదులను గానీ మార్చదు.",
  "Follow up on": "ఫాలో-అప్ తేదీ",
