  "Follow-up date saved.": "ఫాలో-అప్ తేదీ సేవ్ అయింది.",
  "Follow-up marked done.": "ఫాలో-అప్ పూర్తయినట్టు గుర్తించాము.",
  "Follow-up reopened.": "ఫాలో-అప్ మళ్లీ తెరిచాము.",
  "Follow-up status": "ఫాలో-అప్ స్థితి",
  "Food and drink by mouth for comfort, and mouth care, always continue. Tube feeding is a medical treatment and is a choice.": "సౌకర్యం కోసం నోటి ద్వారా తినడం, తాగడం, నోటి సంరక్షణ ఎప్పుడూ కొనసాగుతాయి. గొట్టం ద్వారా ఆహారం ఒక వైద్య చికిత్స, అది మీ ఎంపిక.",
  "Food and drink by mouth, given by hand for comfort, as much as the person wants and can safely swallow.": "సౌకర్యం కోసం చేత్తో నోటికి ఇచ్చే ఆహారం, పానీయం — ఆ వ్యక్తి కోరినంత, సురక్షితంగా మింగగలిగినంత.",
  "for a patient who cannot decide, withholding or withdrawing life-sustaining treatment may need the Medical Board process (Common Cause 2023; Harish Rana 2026). This plan records wishes and clinical limits; it does not by itself legally authorise withholding treatment.": "నిర్ణయం తీసుకోలేని రోగికి ప్రాణాన్ని నిలిపే చికిత్సను మొదలుపెట్టకపోవడానికి లేదా ఆపడానికి మెడికల్ బోర్డ్ ప్రక్రియ అవసరం కావచ్చు (Common Cause 2023; Harish Rana 2026). ఈ ప్లాన్ కోరికలను, వైద్య పరిమితులను నమోదు చేస్తుంది; చికిత్స ఇవ్వకుండా ఉండటానికి ఇది ఒక్కటే చట్టపరమైన అనుమతి కాదు.",
  "For each treatment, choose what you want in those situations. You can leave any as “Not decided”.": "ప్రతి చికిత్సకు, ఆ పరిస్థితుల్లో మీరు ఏమి కోరుకుంటున్నారో ఎంచుకోండి. దేనినైనా “నిర్ణయించలేదు” అని వదిలేయవచ్చు.",
  "For example your municipal corporation or gram panchayat. Maharashtra and Karnataka (rural) have named custodians; Andhra Pradesh has not confirmed one yet. You can still sign and record “custodian pending”.": "ఉదాహరణకు మీ మున్సిపల్ కార్పొరేషన్ లేదా గ్రామ పంచాయతీ. మహారాష్ట్ర, కర్ణాటక (గ్రామీణ) కస్టోడియన్లను పేర్కొన్నాయి; ఆంధ్రప్రదేశ్ ఇంకా ఎవరినీ నిర్ధారించలేదు. అయినా మీరు సంతకం చేసి “కస్టోడియన్ పెండింగ్‌లో ఉంది” అని నమోదు చేయవచ్చు.",
  "For example, the palliative team’s day-and-night number.": "ఉదాహరణకు, పాలియేటివ్ బృందం రాత్రింబవళ్లు పని చేసే నంబర్.",
  "For example: easing worry and confusion so I can spend time with family": "ఉదాహరణకు: కుటుంబంతో సమయం గడపడానికి ఆందోళన, అయోమయం తగ్గించడం",
  "For me": "నా కోసం",
