  "GIST (gastrointestinal stromal tumour)": "GIST (గ్యాస్ట్రోఇంటెస్టినల్ స్ట్రోమల్ ట్యూమర్)",
  "Give a copy to each person below. Ask each one first: their consent to receive it is recorded separately.": "కింద ఉన్న ప్రతి వ్యక్తికి ఒక కాపీ ఇవ్వండి. ముందుగా ఒక్కొక్కరినీ అడగండి: కాపీ తీసుకోవడానికి వారి అంగీకారం వేరుగా నమోదు అవుతుంది.",
  "Give a signed copy to the family. Ambulance crews follow it only when they are handed a copy.": "సంతకం చేసిన కాపీని కుటుంబానికి ఇవ్వండి. అంబులెన్స్ బృందం చేతికి కాపీ ఇచ్చినప్పుడే దానిని పాటిస్తుంది.",
  "Give full standard emergency care when any of these is true:": "వీటిలో ఏది నిజమైనా పూర్తి సాధారణ అత్యవసర చికిత్స ఇవ్వండి:",
