  "I am a registered organ donor (Form 7, THOTA 1994).": "నేను నమోదైన అవయవ దాతను (Form 7, THOTA 1994).",
  "I am doing this by my own free will. Nobody is forcing or pressuring me.": "నేను నా సొంత ఇష్టంతో ఇది చేస్తున్నాను. నన్ను ఎవరూ బలవంతం చేయడం లేదు, ఒత్తిడి చేయడం లేదు.",
  "I am giving a thumb impression": "నేను బొటనవేలి ముద్ర వేస్తున్నాను",
  "I am starting this in the emergency department": "నేను అత్యవసర విభాగంలో దీనిని మొదలుపెడుతున్నాను",
  "I cannot give a number": "నేను సంఖ్య చెప్పలేను",
  "I cannot read or write. Someone wrote this as I said and read it out to me.": "నాకు చదవడం, రాయడం రాదు. నేను చెప్పినట్లు ఒకరు దీనిని రాసి, నాకు చదివి వినిపించారు.",
  "I checked this medicine, dose, food instruction and time against the original prescription.": "ఈ మందు, మోతాదు, భోజన సూచన, సమయాన్ని అసలు ప్రిస్క్రిప్షన్‌తో సరిచూశాను.",
  "I checked this text against the original document.": "ఈ టెక్స్ట్‌ను అసలు పత్రంతో సరిచూశాను.",
  "I do not want": "నాకు వద్దు",
  "I gave someone a copy": "నేను ఎవరికో కాపీ ఇచ్చాను",
  "I gave them this copy": "నేను వారికి ఈ కాపీ ఇచ్చాను",
  "I have checked: the goal is to prioritise life, with these limits on breathing support or ICU.": "నేను తనిఖీ చేశాను: లక్ష్యం ప్రాణానికి ప్రాధాన్యం ఇవ్వడం, శ్వాస సహాయం లేదా ICU పై ఈ పరిమితులతో.",
  "I have talked to them and they agreed to be my representative.": "నేను వారితో మాట్లాడాను, నా ప్రతినిధిగా ఉండటానికి వారు అంగీకరించారు.",
  "I have thought about it carefully.": "నేను దీని గురించి బాగా ఆలోచించాను.",
  "I made this decision now": "ఈ నిర్ణయం నేను ఇప్పుడు తీసుకున్నాను",
  "I reviewed this version. It accurately records our discussion and the decisions written here.": "ఈ వెర్షన్ చూశాను. ఇందులో మా చర్చ, ఇక్కడ రాసిన నిర్ణయాలు సరిగ్గా నమోదయ్యాయి.",
  "I reviewed this version. It accurately records our discussion.": "ఈ వెర్షన్ చూశాను. ఇందులో మా చర్చ సరిగ్గా నమోదైంది.",
  "I understand doctors will not use it if the situation is unclear or one I did not think of.": "పరిస్థితి స్పష్టంగా లేకపోతే లేదా నేను ఊహించని పరిస్థితి అయితే డాక్టర్లు దీనిని వాడరని నాకు అర్థమైంది.",
  "I understand what this document means and what can happen because of it.": "ఈ పత్రం అర్థం ఏమిటో, దీని వల్ల ఏమి జరగవచ్చో నాకు అర్థమైంది.",
  "I want": "నాకు కావాలి",
  "I want to donate my body for medical study.": "వైద్య విద్య కోసం నా శరీరాన్ని దానం చేయాలనుకుంటున్నాను.",
  "I’ve read this": "నేను ఇది చదివాను",
  "ICD (gives shocks)": "ICD (షాక్‌లు ఇస్తుంది)",
  "ICU": "ICU",
  "ID document": "గుర్తింపు పత్రం",
  "ID type": "ID రకం",
  "If a new, reversible problem happens (for example choking or a drug reaction), treat it fully even above this level?": "కొత్తగా, తగ్గగల సమస్య వస్తే (ఉదాహరణకు గొంతులో అడ్డుపడటం లేదా మందు రియాక్షన్), ఈ స్థాయి కంటే పైన అయినా పూర్తి చికిత్స ఇవ్వాలా?",
  "IF IN DOUBT, RESUSCITATE": "సందేహం ఉంటే, CPR చేయండి",
  "IF IN DOUBT, RESUSCITATE. What the patient says now overrides this card.": "సందేహం ఉంటే, CPR చేయండి. రోగి ఇప్పుడు చెప్పేది ఈ కార్డ్ కంటే ముఖ్యం.",
  "If the family disagrees: hold one family meeting, go back to what the patient would want, and ask the ethics committee if still unresolved. Current treatment continues meanwhile.": "కుటుంబం అంగీకరించకపోతే: ఒక కుటుంబ సమావేశం పెట్టండి, రోగి ఏమి కోరుకునేవారో మళ్లీ ఆలోచించండి, అప్పటికీ తేలకపోతే ఎథిక్స్ కమిటీని అడగండి. ఈలోగా ప్రస్తుత చికిత్స కొనసాగుతుంది.",
  "If the patient asks directly, how will we answer honestly?": "రోగి నేరుగా అడిగితే, మనం నిజాయితీగా ఎలా సమాధానం చెబుతాం?",
  "If unclear or the problem is new and reversible — treat fully and call.": "స్పష్టంగా లేకపోతే లేదా సమస్య కొత్తది, తగ్గేది అయితే — పూర్తిగా చికిత్స చేసి కాల్ చేయండి.",
  "Ignore": "పట్టించుకోవద్దు",
  "Illness": "వ్యాధి",
  "Implanted device": "శరీరంలో అమర్చిన పరికరం",
  "Implanted heart device": "గుండెలో అమర్చిన పరికరం",
