  "Intensive care (ICU)": "ఇంటెన్సివ్ కేర్ (ICU)",
  "Is someone answering for the patient?": "రోగి తరఫున ఎవరైనా సమాధానం చెబుతున్నారా?",
  "Issue my emergency card": "నా అత్యవసర కార్డ్ జారీ చేయండి",
  "Issued": "జారీ అయింది",
  "Issuing makes a new private link for the QR code (no name or number in the link) and withdraws any older card. Keep one copy at home, one with the family member who travels with you, and one inside the front door for the ambulance crew.": "జారీ చేస్తే QR కోడ్ కోసం కొత్త ప్రైవేట్ లింక్ తయారవుతుంది (లింక్‌లో పేరు లేదా నంబర్ ఉండదు), పాత కార్డ్ ఉపసంహరించబడుతుంది. ఒక కాపీ ఇంట్లో, ఒకటి మీతో ప్రయాణించే కుటుంబ సభ్యుని దగ్గర, ఒకటి అంబులెన్స్ బృందం కోసం ఇంటి ముందు తలుపు లోపల ఉంచండి.",
  "Issuing…": "జారీ అవుతోంది…",
  "It applies only when your doctors decide there is no reasonable chance you will recover, and more treatment would only make dying longer. Choose the situations:": "మీరు కోలుకునే అవకాశం సహేతుకంగా లేదని, ఇంకా చికిత్స చేస్తే మరణాన్ని మాత్రమే పొడిగిస్తుందని మీ డాక్టర్లు నిర్ణయించినప్పుడే ఇది వర్తిస్తుంది. పరిస్థితులను ఎంచుకోండి:",
  "It cannot ask for anything meant to end life. That is against the law.": "ప్రాణం తీయడం కోసం ఏదీ ఇందులో అడగలేరు. అది చట్టానికి విరుద్ధం.",
  "It is only about refusing treatments that would just prolong dying. Comfort care, pain relief and feeding by mouth always continue.": "ఇది మరణాన్ని పొడిగించే చికిత్సలను మాత్రమే వద్దనడం గురించి. సౌకర్య సంరక్షణ, నొప్పి ఉపశమనం, నోటి ద్వారా తినిపించడం ఎప్పుడూ కొనసాగుతాయి.",
  "It stays “printed, not signed” until all of this is recorded.": "ఇవన్నీ నమోదు అయ్యే వరకు ఇది “ప్రింట్ అయింది, సంతకం కాలేదు” అనే ఉంటుంది.",
  "It takes about 20 minutes. Your answers stay on this device until you print them.": "దీనికి సుమారు 20 నిమిషాలు పడుతుంది. మీరు ప్రింట్ చేసే వరకు మీ సమాధానాలు ఈ పరికరంలోనే ఉంటాయి.",
