  "Legal review pending — for a patient who cannot decide, withholding or withdrawing life-sustaining treatment may need the Medical Board process (Common Cause 2023; Harish Rana 2026).": "చట్టపరమైన పరిశీలన పెండింగ్‌లో ఉంది — నిర్ణయం తీసుకోలేని రోగికి ప్రాణాన్ని నిలిపే చికిత్సను మొదలుపెట్టకపోవడానికి లేదా ఆపడానికి మెడికల్ బోర్డ్ ప్రక్రియ అవసరం కావచ్చు (Common Cause 2023; Harish Rana 2026).",
