  "Live link is on the Sahara server. A copy is also saved on this device for offline use.": "లైవ్ లింక్ సహారా సర్వర్‌లో ఉంది. ఆఫ్‌లైన్ వాడకం కోసం ఒక కాపీ ఈ పరికరంలో కూడా సేవ్ అయింది.",
