  "Removed from your journal.": "మీ డైరీ నుండి తీసేశాము.",
  "Removing a tube that is already in place is stopping treatment. It needs a Primary and a Secondary Medical Board (each usually within 48 hours) and a message to the local magistrate (JMFC). This plan records the wish only. It cannot be used to remove the tube, and the app never starts a withdrawal.": "ఇప్పటికే ఉన్న గొట్టాన్ని తీసివేయడం అంటే చికిత్సను ఆపడమే. దీనికి ప్రైమరీ, సెకండరీ మెడికల్ బోర్డులు (ఒక్కొక్కటి సాధారణంగా 48 గంటల్లో), స్థానిక మేజిస్ట్రేట్‌కు (JMFC) సమాచారం అవసరం. ఈ ప్లాన్ కోరికను మాత్రమే నమోదు చేస్తుంది. గొట్టం తీసివేయడానికి దీనిని వాడలేరు, యాప్ ఎప్పుడూ చికిత్స ఆపడాన్ని మొదలుపెట్టదు.",
  "Removing the existing feeding tube needs the medical board process — not from this record alone.": "ఇప్పటికే ఉన్న ఫీడింగ్ ట్యూబ్ తీసేయాలంటే మెడికల్ బోర్డ్ ప్రక్రియ అవసరం — ఈ రికార్డ్ ఒక్కటే సరిపోదు.",
