  "Sahara prints the paper. It becomes valid only when you sign it by hand in front of two witnesses and a notary or gazetted officer attests it. Then you upload a photo or scan here.": "సహారా కాగితాన్ని ప్రింట్ చేస్తుంది. మీరు ఇద్దరు సాక్షుల ముందు చేత్తో సంతకం చేసి, నోటరీ లేదా గెజిటెడ్ అధికారి ధృవీకరించినప్పుడే ఇది చెల్లుతుంది. తర్వాత ఫోటో లేదా స్కాన్‌ను ఇక్కడ అప్‌లోడ్ చేయండి.",
