  "Signs of dying (falling blood pressure, cold mottled hands and feet, jaw breathing, Cheyne–Stokes breathing, little urine) mean this plan needs urgent review. If the signs are unclear, get a second opinion — wrongly deciding someone is dying can make it come true.": "మరణ సమీప లక్షణాలు (పడిపోతున్న BP, చల్లగా మచ్చలుగా మారిన చేతులు-కాళ్లు, దవడతో శ్వాస, Cheyne–Stokes శ్వాస, చాలా తక్కువ మూత్రం) కనిపిస్తే ఈ ప్లాన్‌ను వెంటనే పరిశీలించాలి. లక్షణాలు స్పష్టంగా లేకపోతే, రెండో అభిప్రాయం తీసుకోండి — ఎవరైనా చనిపోతున్నారని తప్పుగా నిర్ణయిస్తే అదే నిజం కావచ్చు.",
