  "Transport with symptom relief only (O₂ for breathlessness, pain relief, positioning; no CPR, no intubation)": "లక్షణ ఉపశమనంతో మాత్రమే తరలింపు (ఆయాసానికి O₂, నొప్పి ఉపశమనం, సరైన భంగిమ; CPR లేదు, ఇంట్యూబేషన్ లేదు)",
