  "Treating team": "చికిత్స చేస్తున్న బృందం",
  "Treatment": "చికిత్స",
  "Treatment calendar": "చికిత్స క్యాలెండర్",
  "Treatment change": "చికిత్సలో మార్పు",
  "Treatment choices are locked. First record that the illness has been explained as not curable and the family can say it back.": "చికిత్స ఎంపికలు లాక్ అయ్యాయి. వ్యాధి నయం కాదని వివరించారని, కుటుంబం దానిని తిరిగి చెప్పగలదని ముందుగా నమోదు చేయండి.",
  "Treatment dates": "చికిత్స తేదీలు",
  "Treatment event": "చికిత్స ఘట్టం",
  "Treatment events": "చికిత్స ఘట్టాలు",
  "Treatment name": "చికిత్స పేరు",
  "Treatment steps stay locked until this is ticked.": "దీనిని టిక్ చేసే వరకు చికిత్స దశలు లాక్ అయి ఉంటాయి.",
  "Treatment summary": "చికిత్స సారాంశం",
  "Treatments": "చికిత్సలు",
  "Trial": "ప్రయత్నం",
