  "Trial of a set number of sessions or days": "నిర్ణీత సెషన్లు లేదా రోజుల ట్రయల్",
  "Try a report name, a medicine name, or fewer words.": "రిపోర్ట్ పేరు, మందు పేరు, లేదా తక్కువ పదాలతో ప్రయత్నించండి.",
