  "Which version did you give?": "మీరు ఏ వెర్షన్ ఇచ్చారు?",
  "White cell count": "తెల్ల రక్త కణాలు (WBC)",
  "Who and when? (optional)": "ఎవరు, ఎప్పుడు? (ఐచ్ఛికం)",
  "Who are they? (optional)": "వారు ఎవరు? (ఐచ్ఛికం)",
  "Who can help?": "ఎవరు సహాయం చేయగలరు?",
  "Who can see it?": "ఎవరు చూడగలరు?",
  "Who follows up and when? (optional)": "ఎవరు, ఎప్పుడు ఫాలో-అప్ చేస్తారు? (ఐచ్ఛికం)",
  "Who gave these instructions?": "ఈ సూచనలు ఎవరు ఇచ్చారు?",
  "Who has the latest copy?": "తాజా కాపీ ఎవరి దగ్గర ఉంది?",
  "Who is describing this?": "ఇది ఎవరు చెబుతున్నారు?",
  "Who is helping?": "ఎవరు సహాయం చేస్తున్నారు?",
  "Who is signing": "ఎవరు సంతకం చేస్తున్నారు",
  "Who opened or changed this plan": "ఈ ప్లాన్‌ను ఎవరు తెరిచారు లేదా మార్చారు",
  "Who said it?": "ఎవరు చెప్పారు?",
  "Who speaks for the patient if they cannot decide? Store only the ID type and last 4 digits.": "రోగి నిర్ణయం తీసుకోలేకపోతే వారి తరఫున ఎవరు మాట్లాడతారు? ID రకం, చివరి 4 అంకెలు మాత్రమే ఉంచండి.",
  "Who was there": "ఎవరెవరు ఉన్నారు",
  "Who will review (one name per line)": "ఎవరు పరిశీలిస్తారు (ఒక్కో లైన్‌కు ఒక పేరు)",
  "Who would you like with you?": "మీతో ఎవరు ఉండాలని కోరుకుంటున్నారు?",
  "Who wrote the source?": "మూలాన్ని ఎవరు రాశారు?",
  "Who?": "ఎవరు?",
  "Why “do not go to hospital” goes with high-flow oxygen, NIV or ICU": "“ఆసుపత్రికి వెళ్లవద్దు” తో పాటు హై-ఫ్లో ఆక్సిజన్, NIV లేదా ICU ఎందుకు",
  "Why a breathing tube or blood-pressure drugs without ICU": "ICU లేకుండా శ్వాస గొట్టం లేదా బీపీని నిలబెట్టే మందులు ఎందుకు",
  "Why are you withdrawing this card?": "ఈ కార్డ్‌ను ఎందుకు ఉపసంహరిస్తున్నారు?",
  "Why breathing support at home is planned (for example, home NIV)": "ఇంట్లో శ్వాస సహాయం ఎందుకు ప్లాన్ చేశారు (ఉదాహరణకు, ఇంట్లో NIV)",
  "Why CPR is still to be attempted": "అయినా CPR ఎందుకు ప్రయత్నించాలి",
  "Why ICU, blood-pressure drugs or dialysis with a comfort goal": "సౌకర్య లక్ష్యంతో ICU, బీపీని నిలబెట్టే మందులు లేదా డయాలసిస్ ఎందుకు",
  "Why is a review needed?": "పరిశీలన ఎందుకు అవసరం?",
  "Why this person can decide": "ఈ వ్యక్తి ఎందుకు నిర్ణయం తీసుకోగలరు",
  "Why you are making this, and what matters to you (optional)": "మీరు దీనిని ఎందుకు తయారు చేస్తున్నారు, మీకు ఏది ముఖ్యం (ఐచ్ఛికం)",
  "Wish to remove an existing tube is recorded: this is withdrawal and needs the medical board pathway — not actionable from this plan.": "ఉన్న ట్యూబ్ తీసేయాలనే కోరిక నమోదైంది: ఇది చికిత్స ఉపసంహరణ, దీనికి మెడికల్ బోర్డ్ ప్రక్రియ అవసరం — ఈ ప్లాన్ ఆధారంగా అమలు చేయకూడదు.",
  "Wish to remove an existing tube: withdrawal — medical board pathway only.": "ఇప్పటికే ఉన్న గొట్టాన్ని తీసివేయాలనే కోరిక: ఇది చికిత్స ఆపడం — మెడికల్ బోర్డ్ మార్గంలో మాత్రమే.",
  "Wishes about last rites": "అంత్యక్రియల గురించి కోరికలు",
  "Wishes said or written before (not a legal AMD)": "ఇంతకు ముందు చెప్పిన లేదా రాసిన కోరికలు (చట్టపరమైన AMD కాదు)",
  "With food": "భోజనంతో పాటు",
  "Withdraw card": "కార్డ్ ఉపసంహరించండి",
