  "You can change your mind at any time. If you can decide, what you say now counts more than this paper.": "మీరు ఎప్పుడైనా మీ మనసు మార్చుకోవచ్చు. మీరు నిర్ణయం తీసుకోగలిగితే, ఈ కాగితం కంటే మీరు ఇప్పుడు చెప్పేదే ముఖ్యం.",
  "You can mark these done on the day.": "ఆ రోజున వీటిని పూర్తయినట్టు గుర్తించవచ్చు.",
