  "Your latest changes will be saved first.": "మీ తాజా మార్పులు ముందుగా సేవ్ అవుతాయి.",
  "Your list is ready to download.": "మీ జాబితా డౌన్‌లోడ్‌కు సిద్ధంగా ఉంది.",
  "Your moments": "మీ క్షణాలు",
  "Your next step": "మీ తదుపరి పని",
  "Your note is back.": "మీ నోట్ తిరిగి వచ్చింది.",
