  "Admitted to ICU?": "ICU లో చేర్చారా?",
  "After both boards agree, nothing is done for 30 days. In this reconsideration period, anyone affected may go to court (Harish Rana, 2026 INSC 222, para 322(vi)).": "రెండు బోర్డులు అంగీకరించిన తర్వాత 30 రోజులు ఏమీ చేయరు. ఈ పునఃపరిశీలన కాలంలో ప్రభావితులైన ఎవరైనా కోర్టుకు వెళ్లవచ్చు (Harish Rana, 2026 INSC 222, para 322(vi)).",
