  "The living will has changed since this card was issued, so the card shows an old status. Issue a new card.": "ఈ కార్డ్ జారీ చేసిన తర్వాత లివింగ్ విల్ మారింది, కాబట్టి కార్డ్ పాత స్థితి చూపిస్తోంది. కొత్త కార్డ్ జారీ చేయండి.",
