  "The unsigned draft is deleted from this device. Signed versions and the log were kept.": "సంతకం లేని డ్రాఫ్ట్ ఈ పరికరం నుండి తొలగించాము. సంతకం చేసిన వెర్షన్లు, లాగ్ ఉంచాము.",
  "There is no unsigned draft to delete. A draft that someone has already signed is kept.": "తొలగించడానికి సంతకం లేని డ్రాఫ్ట్ లేదు. ఎవరైనా ఇప్పటికే సంతకం చేసిన డ్రాఫ్ట్ అలాగే ఉంటుంది.",
  "This card was withdrawn on {0}.": "ఈ కార్డ్‌ను {0} న వెనక్కి తీసుకున్నారు.",
  "This card was withdrawn.": "ఈ కార్డ్‌ను వెనక్కి తీసుకున్నారు.",
  "This deletes the unsigned draft from this device. It cannot be undone. Signed versions and the log stay.": "ఇది సంతకం లేని డ్రాఫ్ట్‌ను ఈ పరికరం నుండి తొలగిస్తుంది. దీన్ని తిరిగి తేలేము. సంతకం చేసిన వెర్షన్లు, లాగ్ అలాగే ఉంటాయి.",
  "This device has no voice for this language, so it may not read clearly. You can add one in the phone’s language settings.": "ఈ పరికరంలో ఈ భాషకు వాయిస్ లేదు, కాబట్టి స్పష్టంగా చదవకపోవచ్చు. ఫోన్ భాష సెట్టింగ్స్‌లో ఒకటి జోడించవచ్చు.",
  "This file is too large. Use one under 15 MB.": "ఈ ఫైల్ చాలా పెద్దది. 15 MB కంటే చిన్నది వాడండి.",
  "This plan still lists one. Check with the decision-maker": "ఈ ప్లాన్‌లో ఇంకా ఒకటి ఉన్నట్లు ఉంది. నిర్ణయం తీసుకునే వ్యక్తిని అడిగి తెలుసుకోండి",
  "Tick a box or write what happened.": "ఒక బాక్స్‌లో టిక్ పెట్టండి లేదా ఏమి జరిగిందో రాయండి.",
  "Too many reminders to this number in the last hour. No message was sent.": "గత గంటలో ఈ నంబర్‌కు చాలా రిమైండర్లు వెళ్లాయి. సందేశం పంపలేదు.",
